export function getItemIconUrl(itemOrCrop) {
    if (!itemOrCrop) return null;
    return ITEM_ICONS[itemOrCrop] || ITEM_ICONS[itemOrCrop.toLowerCase()] || null;
}

export function getFacilityGlyphUrl(facilityName) {
    return FACILITY_GLYPHS[facilityName] || null;
}

export function getRecommendedWorker(facilityName) {
    return RECOMMENDED_WORKERS[facilityName] || null;
}


