export const ABILITY_TH_MAP = {
    'Fire': 'ไฟ', 'Grass': 'หญ้า', 'Water': 'น้ำ', 'Earth': 'ดิน',
    'Lightning': 'สายฟ้า', 'Ice': 'น้ำแข็ง', 'Wind': 'ลม', 'Dark': 'ความมืด',
    'Light': 'ส่องแสง', 'Hauling': 'แบก', 'Artisanship': 'ช่างฝีมือ',
    'Leisure': 'ไม่รีบร้อน', 'Perfumery': 'การผลิตน้ำหอม'
};

export function findAniimosByAbility(ability, minLevel = 1) {
    if (!ability) return [];
    const engAbility = Object.keys(ABILITY_TH_MAP).find(k => k.toLowerCase() === ability.toLowerCase() || ABILITY_TH_MAP[k] === ability) || ability;
    return ALL_ANIIMOS
        .filter(a => a.skills && a.skills[engAbility] >= minLevel)
        .sort((a, b) => (b.skills[engAbility] || 0) - (a.skills[engAbility] || 0));
}

export function getBestAniimoForFacility(facilityName, ability, minLevel = 1) {
    if (RECOMMENDED_WORKERS[facilityName]) {
        return RECOMMENDED_WORKERS[facilityName];
    }
    const candidates = findAniimosByAbility(ability, minLevel);
    if (candidates.length > 0) {
        const top = candidates[0];
        const engAbility = Object.keys(ABILITY_TH_MAP).find(k => k.toLowerCase() === (ability || '').toLowerCase() || ABILITY_TH_MAP[k] === ability) || ability;
        return {
            name: top.name,
            nameEn: top.slug,
            ability: engAbility,
            abilityTh: ABILITY_TH_MAP[engAbility] || engAbility,
            level: top.skills[engAbility] || minLevel,
            avatar: top.avatar
        };
    }
    return null;
}


